head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.qnaId;
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = "ULDSTF30331.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    //공문 개별조회
    url = "/qnaResult.do?method=readQNA&QUES_ID=" + scwin.qnaId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_qnaInfo.DataID = encodeURI(url);
    dts_qnaInfo.reset();
};
scwin.fn_save = function() {
    //공문수정
    if ($c.stf.getStringSize(ans_contn.Text) > 2000) {
        $c.win.alert("[ 답변내용 ] 의 최대입력은 [ 2000 ] byte 입니다.    \n\n[ " + $c.stf.getStringSize(ans_contn.Text) + " ] byte 입니다. 확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        ans_contn.focus();
        return false;
    }
    if (window.confirm("[저장]하시겠습니까?")) {
        dts_input.removeAll();
        dts_input.insertRow();
        dts_input.setCellData(dts_input.getRowPosition(), "EMP_NO", scwin.gEmpNo);
        dts_input.setCellData(dts_input.getRowPosition(), "ANS_CONTN", ans_contn.Text);
        dts_input.setCellData(dts_input.getRowPosition(), "QUES_ID", scwin.qnaId);
        trs_input.Action = "/qnaResult.do?method=saveQNA" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_input.KeyName = "toinb_dataid4";
        trs_input.KeyValue = "JSP(I:pInput=dts_input)";
        trs_input.Post();
    }
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.btn_Cave_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_readOfficialInfo_OnLoadCompleted = function(rowcount) {
    scwin.gEmpNo = dts_readOfficialInfo.getCellData(1, "WRTR_EMP_NO");
    //alert(js_emp_no +'=='+ gEmpNo);

    // 등록자만 삭제/수정버튼이 보이도록 수정 : 2008.08.07 이연숙대리 요청
    if (js_emp_no == scwin.gEmpNo) {
        $c.stf.showObj(btn_save, true);
        $c.stf.showObj(btn_delete, true);
    } else {
        $c.stf.showObj(btn_save, false);
        $c.stf.showObj(btn_delete, false);
    }
};
scwin.trs_input_OnFail = function() {
    $c.stf.alert_error(trs_input);
};
scwin.trs_input_OnSuccess = async function() {
    $c.win.alert("답변을 저장하였습니다");
    frame.opener.fn_search();
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    getId = $c.frame.path("../").fn_getId;
    scwin.qnaId = getId();
    scwin.fn_read();
    dts_input.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_QNA_SAVE_INOUT";
    dts_input.reset();
};
